let planListScope=null,planDesk=null,planKonvaPromise=null;
let planViewSequence=0;
function planAccessKey(){return JSON.stringify([typeof activeSocleOrganizationId==='undefined'?globalThis.socleCurrentOrganizationId||'':activeSocleOrganizationId,globalThis.socleCurrentAccess||null,globalThis.socleAccessPreview||null,Boolean(globalThis.socleLimitedSession)])}
function beginPlanRequest(){return{sequence:++planViewSequence,access:planAccessKey(),view:typeof view==='undefined'?null:view,job:typeof currentJobId==='undefined'?null:currentJobId,child:document.querySelector('#modalbody')?.firstElementChild}}
function ownsPlanRequest(request){return request.sequence===planViewSequence&&request.access===planAccessKey()&&request.view===(typeof view==='undefined'?null:view)&&request.job===(typeof currentJobId==='undefined'?null:currentJobId)&&request.child===document.querySelector('#modalbody')?.firstElementChild}
function planDeskIsCurrent(desk){return planDesk===desk&&(!desk.accessKey||desk.accessKey===planAccessKey())&&desk.root?.isConnected!==false}
function planHasUnsavedChanges(desk=planDesk){return Boolean(desk&&(desk.dirty||desk.pending?.length||desk.dragBefore||desk.symbolEditor?.dirty||desk.symbolEditor?.stroke?.length))}
function formatPlanDate(value){const date=new Date(value);return Number.isNaN(date.getTime())?'':new Intl.DateTimeFormat('fr-BE',{dateStyle:'medium',timeStyle:'short',timeZone:'Europe/Brussels'}).format(date)}
function disposePlanDesk(){if(!planDesk)return;const desk=planDesk;planDesk=null;desk.disposed=true;desk.renderTask?.cancel();desk.stage?.destroy();desk.loadingTask?.destroy().catch(()=>{})}
const closeModalBeforePlans=closeModal;closeModal=function(...args){if(planHasUnsavedChanges()&&planDesk.root.isConnected&&!confirm('Fermer sans enregistrer les annotations ?'))return;planViewSequence++;disposePlanDesk();return closeModalBeforePlans(...args)};
async function loadPlanKonva(){if(globalThis.Konva)return Konva;if(!planKonvaPromise)planKonvaPromise=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='/konva.js?v=10.9.0';script.onload=()=>resolve(Konva);script.onerror=()=>{planKonvaPromise=null;reject(Error('Le dessin du plan ne peut pas être chargé.'))};document.head.append(script)});return planKonvaPromise}
async function openPlanList(scope){
 let request;try{if(planHasUnsavedChanges()&&!confirm('Quitter sans enregistrer les annotations ?'))return;disposePlanDesk();request=beginPlanRequest();scope=Object.fromEntries(Object.entries(scope).filter(([,v])=>v));planListScope=scope;const data=await serverJson('/api/plans?'+new URLSearchParams(scope));if(!ownsPlanRequest(request))return;modal('Plans et mesures',`<section id="planList"><p>Plans privés du bureau, conservés par révision. Les annotations et mesures restent liées au fichier et à sa page. L’import et l’approbation terrain sont séparés : une nouvelle révision reste au bureau jusqu’à validation explicite.</p><button class="btn primary" onclick="planUploadForm()">Ajouter un plan PDF</button>${data.plans.map(p=>'<button class="plan-list-row" onclick="openPlanDesk(\''+esc(p.id)+'\')"><strong>'+esc(p.title)+'</strong><span>Ouvrir le plan et ses révisions →</span></button>').join('')||'<p>Aucun plan dans ce dossier.</p>'}</section>`)}catch(e){if(request&&ownsPlanRequest(request))toast(e.message)}
}
async function planUploadForm(planId=null){
 let request;try{if(planHasUnsavedChanges()&&!confirm('Quitter sans enregistrer les annotations ?'))return;
  request=beginPlanRequest();const scope={...(planListScope||{})};
  const data=planId?await serverJson('/api/plans/'+encodeURIComponent(planId)):null;if(!ownsPlanRequest(request))return;const docs=await serverJson(documentRegistryUrl({q:'',documentType:'technical',origin:'',limit:250}));
  if(!ownsPlanRequest(request))return;disposePlanDesk();modal(planId?'Nouvelle révision du plan':'Ajouter un plan PDF',`<form id="planUpload" onsubmit="savePlanUpload(event)" data-plan-id="${esc(planId||'')}" data-version="${data?.versions[0]?.version||0}" data-scope="${esc(JSON.stringify(scope))}"><input type="hidden" name="operationKey" value="plan-${crypto.randomUUID()}">${planId?'':'<label>Titre du plan<input name="title" required maxlength="180"></label>'}<label>PDF privé existant<select name="documentId"><option value="">Importer un nouveau fichier ci-dessous…</option>${(docs.documents||[]).filter(d=>d.contentType==='application/pdf').map(d=>'<option value="'+esc(d.id)+'">'+esc(d.title||d.originalName)+'</option>').join('')}</select></label><label>Nouveau PDF (1,8 Mo maximum)<input name="file" type="file" accept="application/pdf,.pdf"></label><label>Motif / origine de cette révision<textarea name="changeNote" required maxlength="500" placeholder="Ex. plan développé reçu de l’architecte · indice A"></textarea></label><p>Choisissez un document existant ou un fichier, puis vérifiez son contenu dans le lecteur. Une nouvelle révision ne modifie pas les métrés et devis déjà enregistrés et ne remplace pas la révision terrain approuvée tant qu’elle n’est pas validée explicitement.</p><p id="planUploadStatus" role="status"></p><div class="modal-actions"><button class="btn primary" type="submit">Enregistrer cette révision</button></div></form>`);
  const form=document.querySelector('#planUpload');form.addEventListener('input',event=>{form.elements.operationKey.value='plan-'+crypto.randomUUID();if(['file','documentId'].includes(event.target.name)){delete form.dataset.uploadedId;delete form.dataset.fileOperationKey}});
 }catch(e){if(request&&ownsPlanRequest(request))toast(e.message)}
}
async function savePlanUpload(event){
 event.preventDefault();const form=event.target,button=form.querySelector('button[type=submit]');if(button.disabled)return;button.disabled=true;
 try{
  const f=new FormData(form),file=f.get('file'),existing=String(f.get('documentId')||'');if(existing&&file?.size)throw Error('Choisissez le document existant ou le nouveau fichier.');let documentId=existing||form.dataset.uploadedId;
  if(!documentId){if(!file?.size||file.size>1800000||!file.name.toLowerCase().endsWith('.pdf'))throw Error('Choisissez un PDF de 1,8 Mo maximum.');const upload=new FormData();upload.set('file',file);form.dataset.fileOperationKey||='plan-pdf-'+crypto.randomUUID();upload.set('operationKey',form.dataset.fileOperationKey);upload.set('documentType','technical');upload.set('title',file.name);upload.set('origin','manual_upload');const result=await serverJson('/api/documents',{method:'POST',body:upload});documentId=result.document.id;form.dataset.uploadedId=documentId}
  const planId=form.dataset.planId,payload={documentId,operationKey:f.get('operationKey'),changeNote:f.get('changeNote'),...(planId?{expectedVersion:Number(form.dataset.version)}:{...JSON.parse(form.dataset.scope||'{}'),title:f.get('title')})};
  const result=await serverJson('/api/plans'+(planId?'/'+encodeURIComponent(planId)+'/versions':''),{method:'POST',body:JSON.stringify(payload)});if(form.isConnected)await openPlanDesk(result.id);toast('Révision '+result.version+' du plan enregistrée.');
 }catch(e){form.querySelector('#planUploadStatus').textContent=e.message;button.disabled=false}
}
async function openPlanDesk(id,versionId=null){
 let request;try{
  if(planHasUnsavedChanges()&&!confirm('Ouvrir un autre plan sans enregistrer les annotations ?'))return;
  disposePlanDesk();request=beginPlanRequest();const [data]=await Promise.all([serverJson('/api/plans/'+encodeURIComponent(id)),loadPlanKonva(),loadSupplierPdfJs()]);
  if(!ownsPlanRequest(request))return;modal('Plan · '+data.plan.title,`<section id="planDesk" data-plan-id="${esc(id)}"><p class="plan-notice">Vérifiez l’échelle et la révision avant toute mesure. Les fiches déjà diffusées conservent leur version approuvée.</p><div class="plan-toolbar plan-version-controls"><label>Révision<select id="planVersion">${data.versions.map(v=>'<option value="'+esc(v.id)+'">Révision '+v.version+' · '+(v.approved?'APPROUVÉE TERRAIN':'BUREAU')+' · '+esc(v.filename)+' · '+esc(v.changeNote)+'</option>').join('')}</select></label><button class="btn" onclick="planUploadForm(planDesk.plan.id)">Ajouter une révision</button><label>Page<select id="planPage"></select></label><label>Zoom<select id="planZoom"><option value="fit">Ajuster</option><option value="1">100 %</option><option value="1.5">150 %</option><option value="2">200 %</option><option value="3">300 %</option></select></label></div><div id="planApproval"></div><div class="plan-toolbar plan-tool-controls"><label>Outil<select id="planTool"><option value="move">Parcourir / déplacer</option><option value="edit">Modifier les points</option><option value="sketch">Symboles / groupes</option><option value="calibration">Étalonner (2 points)</option><option value="length">Longueur (2 points)</option><option value="area">Surface (contour)</option><option value="opening">Ouverture (contour)</option><option value="note">Repère texte</option></select></label><label class="plan-calibration-setting" hidden>Cote connue (m)<input id="planKnownLength" inputmode="decimal" placeholder="Ex. 10,00"></label><label class="plan-annotation-setting" hidden>Nom de l’annotation<input id="planAnnotationLabel" maxlength="200" placeholder="Ex. gouttière façade"></label><button id="planUndo" class="btn" disabled onclick="undoPlanEdit()">Annuler la modification</button><button id="planRedo" class="btn" disabled onclick="redoPlanEdit()">Rétablir</button><button id="planFinish" hidden class="btn" onclick="finishPlanPolygon()">Terminer le contour</button><button id="planCancel" hidden class="btn" onclick="cancelPlanDrawing()">Annuler le tracé en cours</button></div><p id="planStatus" role="status" aria-live="polite">Chargement du PDF…</p>${planSketchPanel()}<div id="planViewport" class="plan-viewport" tabindex="0" aria-label="Plan, défilement et annotations"><div id="planPaper" class="plan-paper"><canvas id="planPdf"></canvas><div id="planOverlay"></div></div></div><div class="modal-actions"><button id="planSave" class="btn primary" onclick="savePlanAnnotations()">Enregistrer les annotations</button></div><div id="planMeasures"></div><details><summary>Historique des annotations de cette page</summary><div id="planHistory"></div></details><button class="btn" onclick="openPlanList(planListScope||{visitId:planDesk.plan.visitId,projectId:planDesk.plan.projectId})">Retour aux plans</button></section>`);
  planDesk={...data,accessKey:request.access,root:document.querySelector('#planDesk'),pdf:null,stage:null,layer:null,version:null,pageNumber:1,input:null,snapshot:null,dirty:false,pending:[],tool:'move',disposed:false,renderToken:0,saveKey:null};
  const root=planDesk.root;root.querySelector('#planVersion').value=versionId||data.versions[0].id;
  root.querySelector('#planVersion').onchange=async()=>{if(planHasUnsavedChanges()&&!confirm('Quitter cette page sans enregistrer les annotations ?')){root.querySelector('#planVersion').value=planDesk.version.id;return}await loadPlanVersion(root.querySelector('#planVersion').value)};
  root.querySelector('#planPage').onchange=async e=>{if(planHasUnsavedChanges()&&!confirm('Changer de page sans enregistrer les annotations ?')){e.target.value=planDesk.pageNumber;return}await loadPlanPage(Number(e.target.value))};
  root.querySelector('#planZoom').onchange=renderPlanPage;
  root.querySelector('#planTool').onchange=e=>{planDesk.tool=e.target.value;planDesk.pending=[];drawPlanOverlay()};
  root.querySelector('#planKnownLength').oninput=()=>{if(planDesk.input?.calibration){const before=structuredClone(planDesk.input);planDesk.input.calibration.lengthM=root.querySelector('#planKnownLength').value.replace(',','.');rememberPlanEdit(before);markPlanDirty();drawPlanOverlay()}};
  await loadPlanVersion(root.querySelector('#planVersion').value);
 }catch(e){const status=document.querySelector('#planStatus');if(status)status.textContent=e.message;else toast(e.message)}
}
function renderPlanApproval(){
 const desk=planDesk,node=desk?.root?.querySelector('#planApproval');if(!desk?.version||!node)return;const version=desk.version,current=desk.versions[0],approval=version.approval;
 if(version.approved){const historical=desk.versions.find(v=>v.approved)?.id!==version.id,note=/^Migration 0067/.test(approval?.note||'')?'Révision terrain existante conservée.':approval?.note||'Approbation terrain enregistrée.',date=approval?.approvedAt?formatPlanDate(approval.approvedAt):'';node.innerHTML='<div class="notice"><strong>'+(historical?'Révision terrain historique':'Approuvée pour le terrain')+' · révision '+esc(version.version)+'</strong><br>'+esc(note)+(date?' · '+esc(date):'')+(historical?'<br>Une révision plus récente est approuvée pour les nouvelles fiches terrain.':'')+'</div>';return}
 if(version.id!==current?.id){node.innerHTML='<div class="notice">Révision historique non approuvée pour diffusion terrain.</div>';return}
 node.innerHTML='<div class="notice"><strong>Révision bureau · non approuvée terrain.</strong><br>Son import ne remplace pas la révision déjà diffusée aux équipes.</div><div class="form-two"><label>Note d’approbation<input id="planApprovalNote" maxlength="500" placeholder="Ex. Indice B validé pour exécution"></label><button id="planApprove" class="btn primary" onclick="approvePlanVersion()">Approuver pour diffusion terrain</button></div>';
}
async function approvePlanVersion(){
 const desk=planDesk,version=desk?.version,button=desk?.root?.querySelector('#planApprove'),status=desk?.root?.querySelector('#planStatus');if(!desk||!version||!button)return;
 if(desk.dirty||desk.pending?.length||desk.dragBefore||desk.symbolEditor?.dirty||desk.symbolEditor?.stroke?.length){status.textContent='Enregistrez ou annulez les modifications du plan avant de l’approuver.';return}
 const note=desk.root.querySelector('#planApprovalNote')?.value.trim();if(!note){status.textContent='Ajoutez une note d’approbation terrain.';desk.root.querySelector('#planApprovalNote')?.focus();return}
 button.disabled=true;desk.approvalKeys||={};desk.approvalKeys[version.id]||='plan-approval-'+crypto.randomUUID();
 try{await serverJson('/api/plans/'+encodeURIComponent(desk.plan.id)+'/approve',{method:'POST',body:JSON.stringify({planVersionId:version.id,note,operationKey:desk.approvalKeys[version.id]})});if(!planDeskIsCurrent(desk))return;const fresh=await serverJson('/api/plans/'+encodeURIComponent(desk.plan.id));if(!planDeskIsCurrent(desk))return;desk.versions=fresh.versions;desk.annotations=fresh.annotations;desk.version=desk.versions.find(v=>v.id===version.id)||desk.version;renderPlanApproval();const select=desk.root.querySelector('#planVersion');select.innerHTML=desk.versions.map(v=>'<option value="'+esc(v.id)+'">Révision '+v.version+' · '+(v.approved?'APPROUVÉE TERRAIN':'BUREAU')+' · '+esc(v.filename)+' · '+esc(v.changeNote)+'</option>').join('');select.value=version.id;status.textContent='Révision approuvée pour diffusion terrain. Les fiches existantes restent figées ; une nouvelle fiche est nécessaire pour la nouvelle révision.';toast('Révision '+version.version+' approuvée pour le terrain.')}catch(e){status.textContent=e.message;button.disabled=false}
}
async function loadPlanVersion(id){
 const desk=planDesk;if(!desk)return;const sequence=desk.versionSequence=(desk.versionSequence||0)+1;const version=desk.versions.find(v=>v.id===id);desk.root.querySelector('#planSave').disabled=true;desk.stage?.destroy();desk.stage=null;desk.input=null;desk.root.querySelector('#planStatus').textContent='Chargement de la révision…';desk.renderTask?.cancel();await desk.loadingTask?.destroy().catch(()=>{});if(!planDeskIsCurrent(desk)||sequence!==desk.versionSequence)return;desk.pdf=null;desk.version=version;desk.root.dataset.versionId=version.id;desk.dirty=false;renderPlanApproval();
 try{if(version.archived||version.status!=='available')throw Error('Le fichier de cette révision est indisponible dans les documents privés.');const blob=await serverBlob('/api/documents/'+encodeURIComponent(version.documentId)+'/preview');if(!planDeskIsCurrent(desk)||sequence!==desk.versionSequence)return;const loadingTask=SoclePdfJs.getDocument({data:new Uint8Array(await blob.arrayBuffer()),isEvalSupported:false});desk.loadingTask=loadingTask;const pdf=await loadingTask.promise;if(!planDeskIsCurrent(desk)||sequence!==desk.versionSequence){await loadingTask.destroy();return}if(pdf.numPages>1000){await loadingTask.destroy();throw Error('Maximum 1 000 pages dans ce lecteur.')}desk.pdf=pdf;desk.root.querySelector('#planPage').innerHTML=Array.from({length:pdf.numPages},(_,i)=>'<option value="'+(i+1)+'">'+(i+1)+' / '+pdf.numPages+'</option>').join('');await loadPlanPage(1)}catch(e){if(planDeskIsCurrent(desk)&&sequence===desk.versionSequence)desk.root.querySelector('#planStatus').textContent=e.message}
}
async function loadPlanPage(number,snapshotId=null){
 const desk=planDesk;if(!desk?.pdf)return;const sequence=desk.pageSequence=(desk.pageSequence||0)+1,versionId=desk.version.id,versionSequence=desk.versionSequence||0;
 const ownsView=()=>planDeskIsCurrent(desk)&&sequence===desk.pageSequence&&versionId===desk.version.id&&versionSequence===(desk.versionSequence||0);
 desk.root.querySelector('#planSave').disabled=true;desk.renderToken++;desk.renderTask?.cancel();desk.stage?.destroy();desk.stage=null;desk.pdfPage=null;desk.input=null;desk.pageNumber=number;desk.symbolEditor=null;if(desk.root.querySelector('#planSymbolEditor'))desk.root.querySelector('#planSymbolEditor').hidden=true;desk.pending=[];desk.undo=[];desk.redo=[];desk.dragBefore=null;desk.dirty=false;desk.saveKey=null;desk.root.querySelector('#planPage').value=number;
 try{
 const records=desk.annotations.filter(a=>a.planVersionId===desk.version.id&&a.pageNumber===number).sort((a,b)=>b.version-a.version);desk.snapshot=snapshotId?records.find(s=>s.id===snapshotId):records[0];
 const page=await desk.pdf.getPage(number);if(!ownsView())return;const viewport=page.getViewport({scale:1});
 const input=structuredClone(desk.snapshot?.input||{pageNumber:number,pageWidth:viewport.width,pageHeight:viewport.height,calibration:null,annotations:[]});
 if(Math.abs(input.pageWidth-viewport.width)>.01||Math.abs(input.pageHeight-viewport.height)>.01)throw Error('Le format de la page diffère de celui du relevé. Vérifiez la source.');
 desk.pdfPage=page;desk.input=input;
 desk.readOnly=desk.version.id!==desk.versions[0].id||!!snapshotId&&snapshotId!==records[0]?.id;
 desk.root.querySelector('#planKnownLength').value=desk.input.calibration?.lengthM||'';desk.root.querySelector('#planSave').disabled=desk.readOnly;
 desk.root.querySelector('#planHistory').innerHTML=records.map(s=>'<p><button class="link" onclick="viewPlanHistory('+number+',\''+esc(s.id)+'\')">Annotations v'+s.version+'</button> · '+esc(s.createdAt)+'</p>').join('')||'<p>Aucune version enregistrée.</p>';
 desk.root.querySelector('#planZoom').value='fit';await renderPlanPage();
 }catch(error){if(ownsView()){desk.input=null;desk.pdfPage=null;desk.readOnly=true;desk.root.querySelector('#planSave').disabled=true;desk.root.querySelector('#planStatus').textContent=error.message}}
}
async function renderPlanPage(){
 const desk=planDesk;if(!desk?.pdfPage||!desk.input)return;const token=++desk.renderToken;const previousTask=desk.renderTask;previousTask?.cancel();
 try{await previousTask?.promise.catch(()=>{});if(!planDeskIsCurrent(desk)||token!==desk.renderToken)return;
  const paper=desk.root.querySelector('#planPaper'),canvas=desk.root.querySelector('#planPdf'),choice=desk.root.querySelector('#planZoom').value;
  const requested=choice==='fit'?Math.max(.05,(desk.root.querySelector('#planViewport').clientWidth-20)/desk.input.pageWidth):Number(choice);
  const scale=Math.min(requested,Math.sqrt(4000000/(desk.input.pageWidth*desk.input.pageHeight))),viewport=desk.pdfPage.getViewport({scale});desk.displayWidth=viewport.width;desk.displayHeight=viewport.height;
  desk.stage?.destroy();desk.stage=null;paper.style.width=viewport.width+'px';paper.style.height=viewport.height+'px';canvas.width=Math.max(1,Math.floor(viewport.width));canvas.height=Math.max(1,Math.floor(viewport.height));canvas.style.width=viewport.width+'px';canvas.style.height=viewport.height+'px';
  desk.renderTask=desk.pdfPage.render({canvasContext:canvas.getContext('2d'),viewport});await desk.renderTask.promise;if(!planDeskIsCurrent(desk)||token!==desk.renderToken)return;
  Konva.pixelRatio=1;desk.stage=new Konva.Stage({container:'planOverlay',width:viewport.width,height:viewport.height});desk.layer=new Konva.Layer();desk.stage.add(desk.layer);desk.stage.on('pointerclick',event=>{if(event.target!==desk.stage||desk.readOnly||['move','edit'].includes(desk.tool))return;const p=desk.stage.getPointerPosition();if(p)addPlanPoint({x:p.x/desk.displayWidth,y:p.y/desk.displayHeight})});drawPlanOverlay();
 }catch(e){if(e.name!=='RenderingCancelledException'&&planDeskIsCurrent(desk)&&token===desk.renderToken)desk.root.querySelector('#planStatus').textContent=e.message}
}
// Transactional input history, inspired by the independently qualified Mission 02.
// Keeps ALL real annotation kinds and calibration; never stores display pixels.
function rememberPlanEdit(before){const desk=planDesk;if(!desk||desk.readOnly||JSON.stringify(before)===JSON.stringify(desk.input))return;desk.undo||=[];desk.undo.push(structuredClone(before));if(desk.undo.length>100)desk.undo.shift();desk.redo=[]}
function changePlanHistory(from,to){const desk=planDesk;if(!desk||desk.readOnly||desk.dragBefore||desk.symbolEditor||!desk[from]?.length)return;desk[to]||=[];desk[to].push(structuredClone(desk.input));desk.input=desk[from].pop();desk.pending=[];desk.root.querySelector('#planKnownLength').value=desk.input.calibration?.lengthM||'';markPlanDirty();drawPlanOverlay()}
function undoPlanEdit(){changePlanHistory('undo','redo')}
function redoPlanEdit(){changePlanHistory('redo','undo')}
function applyPlanDrag(candidate){const desk=planDesk,before=desk?.dragBefore;if(!before)return;desk.dragBefore=null;let error='';try{SoclePlanGeometry.calculatePlanPage(candidate);desk.input=candidate;rememberPlanEdit(before);if(JSON.stringify(before)!==JSON.stringify(candidate))markPlanDirty()}catch(e){desk.input=before;error=e.message}drawPlanOverlay();if(error)desk.root.querySelector('#planStatus').textContent=error}
function cancelPlanDrag(){const desk=planDesk;if(!desk?.dragBefore)return;desk.input=desk.dragBefore;desk.dragBefore=null;drawPlanOverlay()}
globalThis.addEventListener('pointercancel',cancelPlanDrag,true);
globalThis.addEventListener('touchcancel',cancelPlanDrag,true);
function markPlanDirty(){planDesk.editRevision=(planDesk.editRevision||0)+1;planDesk.dirty=true;planDesk.saveKey=null;planDesk.root.querySelector('#planStatus').textContent='Modifications non enregistrées.'}
function addPlanPoint(point){
 const desk=planDesk;if(!desk||!desk.input||desk.readOnly)return;if(desk.tool==='sketch'){planSketchCommand('new',point);return}if(desk.tool!=='calibration'&&!desk.root.querySelector('#planAnnotationLabel').value.trim()){desk.root.querySelector('#planStatus').textContent='Nommez l’annotation avant de pointer sur le plan.';desk.root.querySelector('#planAnnotationLabel').focus();return}desk.pending.push(point);
 if(desk.tool==='calibration'&&desk.pending.length===2){const before=structuredClone(desk.input);desk.input.calibration={points:desk.pending,lengthM:desk.root.querySelector('#planKnownLength').value.replace(',','.')};desk.pending=[];rememberPlanEdit(before);markPlanDirty()}
 else if(desk.tool==='length'&&desk.pending.length===2||desk.tool==='note'&&desk.pending.length===1)finishPlanAnnotation();
 drawPlanOverlay();
}
function finishPlanAnnotation(){const desk=planDesk,label=desk.root.querySelector('#planAnnotationLabel').value.trim();if(!label){desk.root.querySelector('#planStatus').textContent='Nommez cette annotation puis terminez le tracé.';return}const before=structuredClone(desk.input);desk.input.annotations.push({id:'a-'+crypto.randomUUID(),kind:desk.tool,label,points:desk.pending});desk.pending=[];rememberPlanEdit(before);markPlanDirty()}
